    const game = gamePortForServer(server as unknown as ServerFamilyLike);
    if (game) {
      // The one genuinely game-specific checkpoint: the guest is up and SSH
      // answers, but the game process itself may still be pulling its image and
      // starting its container before its own port opens — a real, observable
      // distinction (not present at all for a plain VPS order), unlike "pulling
      // the image" itself, which happens inside the guest's own cloud-init run
      // with no channel back to this worker to report on.
      await step("Starting the game server…");
      // `ip` is the dedicated public IP or the NAT server's private address —
      // already computed above. Checking against `ip` proves what this check
      // exists to prove: the game process itself bound its port, independent of
      // whether that port has been forwarded to the internet yet.
      const gameCheck = await checkGamePortOpen(ip, game.port, game.protocol);
      if (!gameCheck.ok) {
        throw new Error(
          `game port ${game.port}/${game.protocol} never opened on ${ip} after ` +
            `~${Math.round(gameCheck.elapsedMs / 1000)}s (${gameCheck.attempts} attempt(s); last error: ` +
            `${gameCheck.error}). SSH is up, but the game server itself never started listening, so this ` +
            `server cannot be handed to the customer as ready.`
        );
      }
      // Auto-forward the game's own port for NAT (non-dedicated-IP) servers, so
      // every game server is reachable the moment it's handed to the customer —
      // "plug and play" — instead of requiring a manual PortForward from the
      // dashboard first. Found live: a real paying Minecraft customer with no
      // dedicated IP and zero forwards had no path from any public IP to their
      // game port at all. Dedicated IP servers need no forward — their guest
      // port already IS the public port.
      if (!SANDBOX && !dedicated) {
        try {
          await allocateGameForward(server.nodeId, server.id, game.port, game.protocol);
          const natErr = await syncPortForwardsBestEffort(`provision ${server.hostname} (game port)`);
          if (natErr) console.error(`[worker] game port forward sync failed for ${server.hostname}`, natErr);
        } catch (e) {
          // Never fail the whole provision over this — the server is still usable
          // via the dashboard's existing manual "Add forward" as a fallback.
          console.error(`[worker] auto-forward game port failed for ${server.hostname}`, e);
        }
      }
      // Minecraft subdomain DNS (lib/game-subdomain-dns.ts): the game port is
      // now reachable either way (dedicated IP directly, or the forward just
      // created above), so this can fire unconditionally.
      if (server.subdomain) {
        await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId: server.id } });
      }
    } else if (server.gamePlanId) {
      // A game order whose family we could not map to a port (new game added to
      // GAME_FAMILIES/catalog without a matching lib/games.ts GAME_PORT entry).
      // This is a config gap, not evidence the server is unhealthy — log it
      // loudly for whoever ships the next game, but do not fail a customer's
      // order over our own missing map entry.
      console.error(
        `[worker] provision ${server.hostname}: game order (gamePlanId=${server.gamePlanId}, ` +
          `osTemplate.family=${server.osTemplate?.family ?? "?"}) has no GAME_PORT entry — skipped the game-port check`
      );
    }
  }

  const runningServer = await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", provisioningStep: null } });

  // Deployment confirmation email (transactional, deduped via EmailLog). Runs on
  // the provision money-path, so it is best-effort and must never fail the build.
  try {
    const { sendServerDeployedEmail } = await import("../lib/server-deployed-email");
    await sendServerDeployedEmail(server, (server as any).user);
  } catch (e) {
    console.error("[worker] deployment-confirmation email failed (non-fatal)", e);
  }
  // Tell the partner (best-effort, never blocks provisioning) — only for orders
  // tagged via a partner deep link (see PartnerSourceCapture + payAndDeploy).
  // Most VPS orders are direct Nxeon customers and must never be forwarded to a
  // partner's webhook.
  if (runningServer.partnerSource === "kodely") {
    try {
      const { notifyPartner } = await import("../lib/partner");
      await notifyPartner("vps.provisioned", {
        userId: runningServer.userId,
        serverId: runningServer.id,
        hostname: runningServer.hostname,
        ipAddress: runningServer.ipAddress,
      });
    } catch (e) {
      console.error("[worker] partner notify failed (non-fatal)", e);
    }
  }

  const isImage = server.osTemplate.category !== "PLAIN_OS";
  const sshLine = dedicated
    ? `ssh root@${dedicated.address}`
    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;

  const caveats: string[] = [];
  if (natError) {
    caveats.push(
      `Port forwarding could NOT be confirmed for this server, so the SSH command above may not connect yet — ` +
        `we are not going to pretend otherwise. Support has been alerted (${natError.message.slice(0, 200)}).`

