/**
 * Docker/RCON control primitives for free-tier Minecraft containers on
 * freemc-host — the free-tier equivalent of lib/game-control.ts, which speaks
 * to full Proxmox-VM game servers over SSH+tunnelled RCON. This is much
 * simpler: one SSH hop to the host, then `docker exec <container> ...` for
 * everything, using the CLI tools itzg/docker-minecraft-server already bundles
 * (rcon-cli, mc-monitor) instead of a hand-rolled RCON protocol client.
 *
 * Plain module (no "use server") — imported from both lib/actions-free-minecraft.ts
 * and, in future, a worker sweep, same reasoning as lib/game-control.ts.
 */
import { scryptSync } from "node:crypto";
import type { Client } from "ssh2";
import { exec, execInput, shellQuote } from "./ssh-exec";
import { getFreemcHostCapacity, wouldExceedFreemcCapacity } from "./freemc-capacity";

/**
 * Deterministic per-server RCON password — HMAC-shaped via scrypt off
 * AUTH_SECRET, same derivation pattern as lib/crypto-box.ts's BYOK key (just a
 * different domain-separation salt). Never stored: computed identically at
 * container-creation time and every time we need to talk RCON to it, so a
 * restart/recreate never invalidates it and there's nothing to leak from the DB.
 */
export function rconPasswordFor(ownerId: string): string {
  const secret = process.env.AUTH_SECRET;
  if (!secret || !secret.trim()) throw new Error("AUTH_SECRET is not set — cannot derive RCON password");
  return scryptSync(secret, `nxeon-freemc-rcon:${ownerId}`, 24).toString("base64url");
}

/** Run one command inside a container via `docker exec`. */
async function dockerExec(conn: Client, containerName: string, cmd: string, timeoutMs = 15_000) {
  return exec(conn, `docker exec ${shellQuote(containerName)} ${cmd}`, timeoutMs);
}

export type ServerStatus = {
  running: boolean;
  players: { online: number; max: number } | null;
};

/**
 * Best-effort status via mc-monitor (bundled in the image) — a plain status
 * ping, no RCON auth needed. A stopped/sleeping container (mc-router scaled it
 * to zero) just fails the docker exec, which reads as "not running", not an
 * error — that's the expected, common state for a free server nobody's on.
 */
export async function getFreeServerStatus(conn: Client, containerName: string): Promise<ServerStatus> {
  const inspect = await exec(
    conn,
    `docker inspect -f '{{.State.Running}}' ${shellQuote(containerName)}`,
    10_000,
  );
  if (inspect.code !== 0 || inspect.stdout.trim() !== "true") {
    return { running: false, players: null };
  }
  const status = await dockerExec(
    conn,
    containerName,
    "mc-monitor status --host localhost --port 25565 --json",
    10_000,
  );
  if (status.code !== 0) return { running: true, players: null }; // container up, MC still booting
  try {
    const parsed = JSON.parse(status.stdout);
    const p = parsed?.server_info?.players;
    if (typeof p?.online === "number" && typeof p?.max === "number") {
      return { running: true, players: { online: p.online, max: p.max } };
    }
  } catch {
    /* fall through */
  }
  return { running: true, players: null };
}

export type RconResult = { ok: true; response: string } | { ok: false; error: string };

// Some plugins (EssentialsX's /list override is the one that's bitten us)
// colorize their command output with raw ANSI escape codes, which the RCON
// protocol passes straight through as literal bytes in the response text —
// there's no terminal on the other end to interpret them. Confirmed live: a
// player name came back as "papiguapo\x1b[0m", which then failed every
// caller's name validation (it's not alphanumeric) and broke the inventory
// editor's "pick a valid player" check even with a real player selected.
// Stripped once here so every RCON consumer (players list, Console tab,
// Roles, inventory editor) gets clean text for free.
const ANSI_ESCAPE_RE = /\x1b\[[0-9;]*m/g;

/** One RCON round-trip via the bundled rcon-cli — see lib/game-control.ts's
 *  validateRconCommand for the same input sanitation used on the paid path. */
export async function sendRcon(
  conn: Client,
  containerName: string,
  ownerId: string,
  command: string,
): Promise<RconResult> {
  const password = rconPasswordFor(ownerId);
  const r = await dockerExec(
    conn,
    containerName,
    `env RCON_PASSWORD=${shellQuote(password)} rcon-cli ${shellQuote(command)}`,
    12_000,
  );
  if (r.code !== 0) return { ok: false, error: r.stderr.trim() || "RCON command failed." };
  return { ok: true, response: r.stdout.replace(ANSI_ESCAPE_RE, "").trim() };
}

export type PlayerInfo = { name: string };

/** Parses rcon-cli's `list` response: "There are N of a max of M players online: a, b, c" */
export async function getFreeServerPlayers(
  conn: Client,
  containerName: string,
  ownerId: string,
): Promise<{ ok: true; players: PlayerInfo[] } | { ok: false; error: string }> {
  const r = await sendRcon(conn, containerName, ownerId, "list");
  if (!r.ok) return r;
  const colonIdx = r.response.indexOf(":");
  if (colonIdx === -1) return { ok: true, players: [] };
  const names = r.response
    .slice(colonIdx + 1)
    .split(",")

