import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { withServerSsh, exec } from "../lib/ssh-exec";
import { notifyAdmins } from "./monitor";

/**
 * Periodically opens a real SSH session — using the platform's own stored root
 * password, never printed or logged — against every RUNNING provisioned
 * server (plain VPS and game servers alike). This exists to catch a failure
 * mode that otherwise stays invisible until a customer happens to try
 * something: a server whose guest-side root password silently drifted from
 * what we have on record (e.g. a retried clone/provision step regenerated a
 * password that never actually landed on the guest — see the comment on
 * `password` in worker/index.ts's provision()), or one that stopped accepting
 * SSH for any other reason, while `Server.status` still reads RUNNING and the
 * dashboard shows nothing wrong. Read-only (`echo`) — never mutates the guest.
 *
 * Cursor-paginated and bounded per sweep so a large fleet is covered
 * gradually across sweeps instead of blocking the worker's serial job loop.
 */
const BATCH_SIZE = 25;
let cursor = 0;

export async function sshHealthSweep(): Promise<void> {
  if (SANDBOX) return; // no real SSH in staging

  const where = { status: "RUNNING" as const, vmid: { not: null }, rootPasswordEnc: { not: null } };
  const total = await db.server.count({ where });
  if (total === 0) return;
  if (cursor >= total) cursor = 0;

  const servers = await db.server.findMany({
    where,
    include: { dedicatedIp: { select: { address: true } }, user: { select: { email: true } } },
    orderBy: { id: "asc" },
    skip: cursor,
    take: BATCH_SIZE,
  });
  cursor += servers.length;
  if (servers.length < BATCH_SIZE) cursor = 0; // wrapped past the end of the table

  for (const s of servers) {
    try {
      await withServerSsh(s, (conn) => exec(conn, "echo nxeon-health-ok", 10_000));
    } catch (e: any) {
      const msg = e?.message ?? String(e);
      console.error(`[ssh-health] ${s.hostname} (${s.id}) failed:`, msg);
      await notifyAdmins(
        `SSH health check failed: ${s.hostname}`,
        `"${s.hostname}" (customer ${s.user.email}) shows RUNNING but SSH auth failed: ${msg}. This usually means the stored root password no longer matches the guest after an interrupted provision/reinstall. Check via Impersonate or the console, then resync/reset the password from the server's admin page.`,
        `/admin/servers/${s.id}`
      );
    }
  }
}

