import type { Client } from "ssh2";
import { exec, assertDomain, assert, shellQuote, SETUP_TIMEOUT_MS } from "./ssh-exec";

/**
 * Shared HTTP verification for things we claim are "serving".
 *
 * Lifted verbatim out of worker/apps.ts, which is the file that got this right
 * first and is named in docs/QA-JOURNEY.md as the model. It lived there as two
 * private functions, so worker/websites.ts marked a site ACTIVE with the message
 * "Your nginx site is configured and serving" having made no request of any kind
 * (M7 #4) — and that unverified ACTIVE then gated the SSL flow, so certbot
 * HTTP-01 was offered for a vhost that might not answer at all.
 *
 * The rule this module exists to enforce: an install/config step that exited 0
 * is not evidence that anything is being served. Only a response is.
 */

export type Probe = {
  /** Path on the app's own domain. */
  path: string;
  /** Accepted status codes (default: 200 only). */
  codes?: string[];
  /** Every pattern must be present in the body. */
  require: RegExp[];
  /** No pattern may be present (application-level error pages). */
  reject?: RegExp[];
  /** What passing this probe proves — quoted verbatim in failures. */
  proves: string;
};


/**
 * The remote shell for `httpProbe`, as a pure function.
 *
 * Split out from the SSH call so test/ssl-verify.test.ts can run `sh -n` and
 * `dash -n` over it. A quoting mistake in generated shell passes typecheck, lint
 * and build and then fails on a customer's live server — the same reason
 * test/migration-gate.test.ts parses `srcInventoryScript`.
 *
 * NOTE the `-k`: this probe answers "does this vhost serve this application",
 * and following an app's own http→https redirect to a self-signed or
 * not-yet-issued certificate must not fail that question. It therefore proves
 * NOTHING about TLS trust — use `tlsProbeCommand` for that, which deliberately
 * omits `-k`.
 */
export function httpProbeCommand(domain: string, path: string): string {
  assertDomain(domain);
  assert(/^\/[A-Za-z0-9._/-]*$/.test(path), `Unsupported probe path: ${path}`);
  return (
    `f=$(mktemp); c=$(curl -sS -k -L --max-redirs 5 --max-time 25 ` +
    `--resolve ${shellQuote(`${domain}:80:127.0.0.1`)} --resolve ${shellQuote(`${domain}:443:127.0.0.1`)} ` +
    `-o "$f" -w '%{http_code}' ${shellQuote(`http://${domain}${path}`)} 2>/dev/null); ` +
    `[ -n "$c" ] || c=000; printf 'NXCODE:%s\\n' "$c"; head -c 8192 "$f" 2>/dev/null; rm -f "$f"`
  );
}

/**
 * Fetch one path on the app's own domain FROM INSIDE the VM, with the hostname
 * pinned to 127.0.0.1 (`curl --resolve`). That sends the real Host header, so it
 * genuinely tests "does this vhost serve this application" while remaining
 * correct before the customer's DNS has propagated. Mirrors the probe in
 * worker/migrate-real.ts, which exists because a port check proved only that
 * something was listening while sites returned 502s.
 */
export async function httpProbe(conn: Client, domain: string, path: string): Promise<{ code: string; body: string }> {
  const r = await exec(conn, httpProbeCommand(domain, path), SETUP_TIMEOUT_MS);
  const out = String(r.stdout ?? "");
  const m = /NXCODE:(\d{3})/.exec(out);
  const nl = out.indexOf("\n");
  // Keep newlines: stripping them would glue words together and make markers
  // unmatchable (see probeBody in worker/migrate-real.ts).
  // eslint-disable-next-line no-control-regex
  const body = (nl < 0 ? "" : out.slice(nl + 1)).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, " ");
  return { code: m ? m[1] : "000", body };
}

/**
 * Run every probe for the app. Throws with the real HTTP result on the first
 * failure — an install that cannot be proved is a FAILED install, never a
 * quietly-downgraded one. Returns a one-line proof for the audit trail.
 */
export async function verifyServing(conn: Client, domain: string, probes: Probe[]): Promise<string> {
  const proof: string[] = [];
  for (const p of probes) {
    const { code, body } = await httpProbe(conn, domain, p.path);
    if (!(p.codes ?? ["200"]).includes(code))
      throw new Error(`verification failed: ${p.path} returned HTTP ${code}, so ${p.proves} is not true.`);
    for (const re of p.reject ?? []) {
      const hit = re.exec(body);
      if (hit) throw new Error(`verification failed: ${p.path} returned an application error ("${hit[0].slice(0, 80)}").`);

