async function reprobeAndSettle(conn: Parameters<Parameters<typeof withServerSsh>[1]>[0], domains: string[]): Promise<SiteServingView[]> {
  const results = new Map<string, SiteServingView>();
  for (const d of domains) results.set(d, await probeDomainOnTarget(conn, d));
