}

async function persistServingOutcome(migrationId: string, currentStatus: string, probes: SiteServingView[]): Promise<boolean> {
  const dark = probes.filter((p) => !p.serving);
  const allServing = probes.length > 0 && dark.length === 0;
  // Only ever UPGRADE the honest verdict — a re-check that finds everything live
  // flips COMPLETED_WITH_ISSUES → DONE. Never downgrade (that belongs to the
  // engine's own run, not a spot re-check).
  if (allServing && currentStatus === "COMPLETED_WITH_ISSUES") {
    await db.migration.update({
      where: { id: migrationId },
      data: { status: "DONE", step: "Completed — all sites serving" },
    }).catch(() => {});
  }
  return allServing;
}

/**
 * Re-check (only) whether each site serves now, and flip the migration to DONE
 * if they all do. No bring-up — just an honest re-probe. Cheap; safe to spam.
 */
export async function recheckMigrationServing(migrationId: string): Promise<RemediationResult> {
  const ctx = await ownedMigrationForRemediation(migrationId);
  if ("error" in ctx) return { error: ctx.error };
  const { m, server, user } = ctx;
  const rl = checkRateLimit(`migrate:recheck:${user.id}`, { max: 20, windowMs: 5 * 60 * 1000 });
  if (!rl.ok) return { error: `Please wait ${rl.retryAfterSec}s before checking again.` };
  const domains = migrationProbeDomains(m.items);
  if (!domains.length) return { ok: true, serving: [], dark: [], allServing: false, log: ["No domains to check."] };
  if (SANDBOX) {
    return { ok: true, serving: domains, dark: [], allServing: true, log: ["Sandbox: pretended all sites serve."] };
  }
  try {
    const probes = await withServerSsh(server, (conn) => reprobeAndSettle(conn, domains));
    const allServing = await persistServingOutcome(m.id, m.status, probes);
    revalidatePath("/dashboard/migrate");
    return {
      ok: true,
      serving: probes.filter((p) => p.serving).map((p) => p.domain),
      dark: probes.filter((p) => !p.serving).map((p) => p.domain),
      allServing,
    };
  } catch {
    return { error: "Couldn't reach the new server to check. Try again in a moment." };
  }
}

